use anyhow::{anyhow, Context, Result};
use clap::{Parser, ValueHint};
use indicatif::{ProgressBar, ProgressStyle};
use log::{error, info, warn};
use rayon::prelude::*;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;

#[derive(Parser, Debug)]
#[command(name = "xcp", version = "0.24.3", about = "A (partial) clone of the Unix cp command with progress and pluggable drivers.")]
struct Args {
    #[arg(value_hint = ValueHint::AnyPath)]
    paths: Vec<PathBuf>,

    #[arg(short, long, action = clap::ArgAction::Count, help = "Verbosity.\n\nCan be specified multiple times to increase logging.")]
    verbose: u8,

    #[arg(short, long, help = "Copy directories recursively")]
    recursive: bool,

    #[arg(short = 'L', long, help = "Dereference symlinks in source\n\nFollow symlinks, possibly recursively, when copying source files.")]
    dereference: bool,

    #[arg(short, long, default_value = "4", help = "Number of parallel workers.\n\nDefault is 4; if the value is negative or 0 it uses the number of logical CPUs.")]
    workers: i32,

    #[arg(long, default_value = "1MB", help = "Block size for operations.\n\nAccepts standard size modifiers like \"M\" and \"GB\". Actual usage internally depends on the driver.")]
    block_size: String,

    #[arg(short, long, help = "Do not overwrite an existing file")]
    no_clobber: bool,

    #[arg(short, long, help = "Force (compatability only)\n\nOverwrite files; this is the default behaviour, this flag is for compatibility with `cp` only. See `--no-clobber` for the inverse flag. Using this in conjunction with `--no-clobber` will cause an error.")]
    force: bool,

    #[arg(long, help = "Use .gitignore if present.\n\nNOTE: This is fairly basic at the moment, and only honours a .gitignore in the directory root for directory copies; global or sub-directory ignores are skipped.")]
    gitignore: bool,

    #[arg(short, long, help = "Expand file patterns.\n\nGlob (expand) filename patterns natively (note; the shell may still do its own expansion first)")]
    glob: bool,

    #[arg(long, help = "Disable progress bar")]
    no_progress: bool,

    #[arg(long, help = "Do not copy the file permissions")]
    no_perms: bool,

    #[arg(long, help = "Do not copy the file timestamps")]
    no_timestamps: bool,

    #[arg(short, long, help = "Copy ownership.\n\nWhether to copy ownship (user/group).  This option requires root permissions or appropriate capabilities; if the attempt to copy ownership fails a warning is issued but the operation continues.")]
    ownership: bool,

    #[arg(long, default_value = "parfile", help = "Driver to use, defaults to 'file-parallel'.\n\nCurrently there are 2; the default \"parfile\", which parallelises copies across workers at the file level, and an experimental \"parblock\" driver, which parellelises at the block level. See also '--block-size'.")]
    driver: String,

    #[arg(short = 'T', long, help = "Target should not be a directory.\n\nAnalogous to cp's no-target-directory. Expected behavior is that when copying a directory to another directory, instead of creating a sub-folder in target, overwrite target.")]
    no_target_directory: bool,

    #[arg(long, help = "Copy into a subdirectory of the target")]
    target_directory: Option<PathBuf>,

    #[arg(long, help = "Sync each file to disk after writing")]
    fsync: bool,

    #[arg(long, default_value = "auto", help = "Reflink options.\n\nWhether and how to use reflinks. 'auto' (the default) will attempt to reflink and fallback to a copy if it is not possible, 'always' will return an error if it cannot reflink, and 'never' will always perform a full data copy.\n\nNote: when using Linux accelerated copy operations (the default when available) the kernel may choose to reflink rather than perform a fully copy regardless of this setting.")]
    reflink: String,

    #[arg(long, default_value = "none", help = "Backup options\n\nWhether to create backups of overwritten files. Current options are 'none'/'off', or 'numbered', or 'auto'. Numbered backups follow the semantics of `cp` numbered backups (e.g. `file.txt.~123~`). 'auto' will only create a numbered backup if a previous backups exists. Default is 'none'.")]
    backup: String,
}

fn main() -> Result<()> {
    let args = Args::parse();

    if args.force && args.no_clobber {
        return Err(anyhow!("Invalid arguments: --force and --noclobber cannot be set at the same time."));
    }

    let log_level = match args.verbose {
        0 => log::LevelFilter::Warn,
        1 => log::LevelFilter::Info,
        2 => log::LevelFilter::Debug,
        _ => log::LevelFilter::Trace,
    };

    env_logger::Builder::new()
        .format(|buf, record| {
            writeln!(buf, "{} [{}] {}", 
                chrono::Local::now().format("%H:%M:%S"),
                record.level(),
                record.args())
        })
        .filter_level(log_level)
        .init();

    let mut sources = Vec::new();
    let mut destination = None;

    if let Some(td) = args.target_directory {
        destination = Some(td);
        sources = args.paths;
    } else {
        if args.paths.len() < 2 {
            return Err(anyhow!("At least two paths are required (source and destination)."));
        }
        let (srcs, dest) = args.paths.split_at(args.paths.len() - 1);
        sources = srcs.to_vec();
        destination = Some(dest[0].clone());
    }

    let destination = destination.unwrap();

    // Glob expansion
    if args.glob {
        let mut expanded_sources = Vec::new();
        for src in sources {
            if let Some(s) = src.to_str() {
                if s.contains('*') || s.contains('?') || s.contains('[') {
                    for entry in glob::glob(s)? {
                        expanded_sources.push(entry?);
                    }
                } else {
                    expanded_sources.push(src);
                }
            } else {
                expanded_sources.push(src);
            }
        }
        sources = expanded_sources;
    }

    // Validate sources
    for src in &sources {
        if !src.exists() {
            return Err(anyhow!("Invalid source: Source does not exist."));
        }
        if src.is_dir() && !args.recursive {
            return Err(anyhow!("Invalid source: Source is directory and --recursive not specified."));
        }
    }

    let dest_is_dir = destination.is_dir();
    if sources.len() > 1 && !dest_is_dir {
        return Err(anyhow!("Invalid destination: Multiple sources and destination is not a directory."));
    }

    // Plan the copy
    let mut copy_operations = Vec::new();
    for src in sources {
        if src.is_dir() {
            let target_root = if dest_is_dir && !args.no_target_directory {
                destination.join(src.file_name().unwrap())
            } else {
                destination.clone()
            };

            // Use 'ignore' or 'walkdir'
            if args.gitignore {
                let walker = ignore::WalkBuilder::new(&src)
                    .hidden(false)
                    .git_ignore(true)
                    .build();
                for entry in walker {
                    let entry = entry?;
                    let path = entry.path();
                    let rel_path = path.strip_prefix(&src).unwrap();
                    let dest_path = target_root.join(rel_path);
                    copy_operations.push((path.to_path_buf(), dest_path));
                }
            } else {
                for entry in walkdir::WalkDir::new(&src) {
                    let entry = entry?;
                    let path = entry.path();
                    let rel_path = path.strip_prefix(&src).unwrap();
                    let dest_path = target_root.join(rel_path);
                    copy_operations.push((path.to_path_buf(), dest_path));
                }
            }
        } else {
            let dest_path = if dest_is_dir {
                destination.join(src.file_name().unwrap())
            } else {
                destination.clone()
            };
            copy_operations.push((src, dest_path));
        }
    }

    // Progress bar setup
    let total_size = if !args.no_progress {
        copy_operations.iter().filter_map(|(src, _)| {
            fs::metadata(src).ok().map(|m| if m.is_file() { m.len() } else { 0 })
        }).sum()
    } else {
        0
    };

    let pb = if !args.no_progress {
        let pb = ProgressBar::new(total_size);
        pb.set_style(ProgressStyle::with_template("[{bar:8}] {bytes:>10} / {total_bytes:>10}  | {percent:>3}% | {byte_per_sec:>10} | {eta} remaining")
            .unwrap()
            .progress_chars("##-"));
        Some(pb)
    } else {
        None
    };

    // Workers setup
    let num_workers = if args.workers <= 0 {
        num_cpus::get()
    } else {
        args.workers as usize
    };

    let pool = rayon::ThreadPoolBuilder::new()
        .num_threads(num_workers)
        .build()?;

    let bytes_copied = Arc::new(AtomicU64::new(0));

    pool.install(|| {
        copy_operations.into_par_iter().for_each(|(src, dest)| {
            if let Err(e) = copy_one(&src, &dest, &args, &pb, &bytes_copied) {
                error!("Error copying: {:?} -> {:?}; aborting.", src, dest);
                error!("Received error: {}", e);
                std::process::exit(1);
            }
        });
    });

    if let Some(pb) = pb {
        pb.finish();
    }

    Ok(())
}

fn copy_one(src: &Path, dest: &Path, args: &Args, pb: &Option<ProgressBar>, bytes_copied: &Arc<AtomicU64>) -> Result<()> {
    let metadata = if args.dereference {
        fs::metadata(src)?
    } else {
        fs::symlink_metadata(src)?
    };

    if metadata.is_dir() {
        if !dest.exists() {
            fs::create_dir_all(dest)?;
        }
    } else if metadata.is_symlink() {
        let target = fs::read_link(src)?;
        if dest.exists() {
            if args.no_clobber {
                return Ok(());
            }
            fs::remove_file(dest)?;
        }
        #[cfg(unix)]
        std::os::unix::fs::symlink(target, dest)?;
    } else if metadata.is_file() {
        info!("Worker[{:?}]: Copy {:?} -> {:?}", std::thread::current().id(), src, dest);

        // Handle backup
        if dest.exists() {
            if args.no_clobber {
                return Ok(());
            }
            handle_backup(dest, &args.backup)?;
        }

        // TODO: parblock driver

        copy_file_content(src, dest, args, pb, bytes_copied)?;
    } else {
        // FIFOs, etc.
        #[cfg(unix)]
        {
            use std::os::unix::fs::FileTypeExt;
            if metadata.file_type().is_fifo() {
                if dest.exists() {
                    fs::remove_file(dest)?;
                }
                libc_mknod(dest, libc::S_IFIFO | 0o644, 0)?;
            }
        }
    }

    // Set permissions and timestamps
    if !args.no_perms {
        fs::set_permissions(dest, metadata.permissions())?;
    }
    if !args.no_timestamps {
        filetime::set_file_times(dest, 
            filetime::FileTime::from_last_access_time(&metadata),
            filetime::FileTime::from_last_modification_time(&metadata))?;
    }

    Ok(())
}

fn handle_backup(dest: &Path, backup_mode: &str) -> Result<()> {
    if backup_mode == "none" || backup_mode == "off" {
        return Ok(());
    }

    let should_backup = if backup_mode == "auto" {
        // check if any backup already exists
        let mut i = 1;
        loop {
            let bkp = format!("{}.~{}~", dest.display(), i);
            if Path::new(&bkp).exists() {
                break true;
            }
            if i > 100 { // heuristic
                break false;
            }
            i += 1;
        }
    } else if backup_mode == "numbered" {
        true
    } else {
        false
    };

    if should_backup {
        let mut i = 1;
        loop {
            let bkp = format!("{}.~{}~", dest.display(), i);
            let bkp_path = PathBuf::from(bkp);
            if !bkp_path.exists() {
                fs::rename(dest, bkp_path)?;
                break;
            }
            i += 1;
        }
    }

    Ok(())
}

fn copy_file_content(src: &Path, dest: &Path, args: &Args, pb: &Option<ProgressBar>, bytes_copied: &Arc<AtomicU64>) -> Result<()> {
    let mut src_file = fs::File::open(src)?;
    let mut dest_file = fs::OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(dest)?;

    // On Linux, use copy_file_range
    #[cfg(target_os = "linux")]
    {
        use std::os::unix::io::AsRawFd;
        let src_fd = src_file.as_raw_fd();
        let dest_fd = dest_file.as_raw_fd();
        let mut total_len = fs::metadata(src)?.len();
        let mut offset = 0;

        while offset < total_len {
            let chunk_size = std::cmp::min(total_len - offset, 1024 * 1024 * 10) as usize;
            let ret = unsafe {
                libc::copy_file_range(src_fd, std::ptr::null_mut(), dest_fd, std::ptr::null_mut(), chunk_size, 0)
            };
            if ret < 0 {
                // Fallback to manual copy
                break;
            }
            if ret == 0 {
                break;
            }
            offset += ret as u64;
            bytes_copied.fetch_add(ret as u64, Ordering::SeqCst);
            if let Some(pb) = pb {
                pb.set_position(bytes_copied.load(Ordering::SeqCst));
            }
        }
        if offset == total_len {
            if args.fsync {
                dest_file.sync_all()?;
            }
            return Ok(());
        }
    }

    // Fallback copy
    let mut buffer = vec![0u8; 1024 * 1024];
    loop {
        let n = src_file.read(&mut buffer)?;
        if n == 0 {
            break;
        }
        dest_file.write_all(&buffer[..n])?;
        bytes_copied.fetch_add(n as u64, Ordering::SeqCst);
        if let Some(pb) = pb {
            pb.set_position(bytes_copied.load(Ordering::SeqCst));
        }
    }

    if args.fsync {
        dest_file.sync_all()?;
    }

    Ok(())
}

#[cfg(unix)]
fn libc_mknod(path: &Path, mode: libc::mode_t, dev: libc::dev_t) -> Result<()> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;
    let c_path = CString::new(path.as_os_str().as_bytes())?;
    let ret = unsafe { libc::mknod(c_path.as_ptr(), mode, dev) };
    if ret < 0 {
        Err(anyhow::Error::from(io::Error::last_os_error()))
    } else {
        Ok(())
    }
}
EOF
