        sources = srcs.to_vec();
        destination = Some(dest[0].clone());
    }

    let destination = destination.unwrap();

    // Glob expansion
    if args.glob {
        let mut expanded_sources = Vec::new();
        for src in sources {
            if let Some(s) = src.to_str() {
                if s.contains('*') || s.contains('?') || s.contains('[') {
                    for entry in glob::glob(s)? {
                        expanded_sources.push(entry?);
                    }
                } else {
                    expanded_sources.push(src);
                }
            } else {
                expanded_sources.push(src);
            }
        }
        sources = expanded_sources;
    }

    // Validate sources
    for src in &sources {
        if !src.exists() {
            return Err(anyhow!("Invalid source: Source does not exist."));
        }
        if src.is_dir() && !args.recursive {
            return Err(anyhow!("Invalid source: Source is directory and --recursive not specified."));
        }
    }

    let dest_is_dir = destination.is_dir();
    if sources.len() > 1 && !dest_is_dir {
        return Err(anyhow!("Invalid destination: Multiple sources and destination is not a directory."));
    }

    // Plan the copy
    let mut copy_operations = Vec::new();
    for src in sources {
        if src.is_dir() {
            let target_root = if dest_is_dir && !args.no_target_directory {
                destination.join(src.file_name().unwrap())
            } else {
                destination.clone()
            };

            if args.gitignore {
                let walker = ignore::WalkBuilder::new(&src)
                    .hidden(false)
                    .git_ignore(true)
                    .build();
                for entry in walker {
                    let entry = entry?;
                    let path = entry.path();
                    let rel_path = path.strip_prefix(&src).unwrap();
                    let dest_path = target_root.join(rel_path);
                    copy_operations.push((path.to_path_buf(), dest_path));
                }
            } else {
                for entry in walkdir::WalkDir::new(&src) {
                    let entry = entry?;
                    let path = entry.path();
                    let rel_path = path.strip_prefix(&src).unwrap();
                    let dest_path = target_root.join(rel_path);
                    copy_operations.push((path.to_path_buf(), dest_path));
                }
            }
        } else {
            let dest_path = if dest_is_dir {
                destination.join(src.file_name().unwrap())
            } else {
                destination.clone()
            };
            copy_operations.push((src, dest_path));
        }
    }

    // Progress bar setup
    let total_size = if !args.no_progress {
        copy_operations.iter().filter_map(|(src, _)| {
            fs::symlink_metadata(src).ok().map(|m| if m.is_file() { m.len() } else { 0 })
        }).sum()
    } else {
        0
    };

    let pb = if !args.no_progress {
        let pb = ProgressBar::new(total_size);
        pb.set_style(ProgressStyle::with_template("[{bar:8}] {bytes:>10} / {total_bytes:>10}  | {percent:>3}% | {byte_per_sec:>10} | {eta} remaining")
            .unwrap()
            .progress_chars("##-"));
        Some(pb)
    } else {
        None
    };

    // Workers setup
    let num_workers = if args.workers <= 0 {
        num_cpus::get()
    } else {
        args.workers as usize
    };

    let pool = rayon::ThreadPoolBuilder::new()
        .num_threads(num_workers)
        .build()?;

    let bytes_copied = Arc::new(AtomicU64::new(0));
    let args_arc = Arc::new(args);
    let pb_arc = Arc::new(pb);

    pool.install(|| {
        copy_operations.into_par_iter().for_each(|(src, dest)| {
            if let Err(e) = copy_one(&src, &dest, &args_arc, &pb_arc, &bytes_copied) {
                error!("Error copying: {:?} -> {:?}; aborting.", src, dest);
                error!("Received error: {}", e);
                std::process::exit(1);
            }
        });
    });

    if let Some(pb) = pb_arc.as_ref() {
        pb.finish();
    }

    Ok(())
}

fn copy_one(src: &Path, dest: &Path, args: &Args, pb: &Arc<Option<ProgressBar>>, bytes_copied: &Arc<AtomicU64>) -> Result<()> {
    let metadata = if args.dereference {
        fs::metadata(src)?
    } else {
        fs::symlink_metadata(src)?
    };

    if metadata.is_dir() {
        if !dest.exists() {
            fs::create_dir_all(dest)?;
        }
    } else if metadata.is_symlink() {
        let target = fs::read_link(src)?;
        if dest.exists() {
            if args.no_clobber {
                return Ok(());
            }
            fs::remove_file(dest)?;
        }
        #[cfg(unix)]
        std::os::unix::fs::symlink(target, dest)?;
    } else if metadata.is_file() {
        if dest.exists() {
            if args.no_clobber {
                return Ok(());
            }
            handle_backup(dest, &args.backup)?;
        }

        if args.driver == "parblock" {
            copy_parblock(src, dest, args, pb, bytes_copied)?;
        } else {
            info!("Worker[{:?}]: Copy {:?} -> {:?}", std::thread::current().id(), src, dest);
            copy_parfile(src, dest, args, pb, bytes_copied)?;
        }
    } else {
        #[cfg(unix)]
        {
            use std::os::unix::fs::FileTypeExt;
            if metadata.file_type().is_fifo() {
                if dest.exists() {
                    fs::remove_file(dest)?;
                }
                libc_mknod(dest, libc::S_IFIFO | 0o644, 0)?;
            }
        }
    }

    if !args.no_perms {
        fs::set_permissions(dest, metadata.permissions()).ok();
    }
    if !args.no_timestamps {
        filetime::set_file_times(dest, 
            filetime::FileTime::from_last_access_time(&metadata),
            filetime::FileTime::from_last_modification_time(&metadata)).ok();
    }

    Ok(())
}

fn handle_backup(dest: &Path, backup_mode: &str) -> Result<()> {
    if backup_mode == "none" || backup_mode == "off" {
        return Ok(());
    }

    let should_backup = if backup_mode == "auto" {
        let mut i = 1;
        let mut exists = false;
        loop {
            let bkp = format!("{}.~{}~", dest.display(), i);
            if Path::new(&bkp).exists() {
                exists = true;
                break;
            }
            if i > 10 { break; }
            i += 1;
        }
        exists
    } else if backup_mode == "numbered" {
        true
    } else {
        false
    };

    if should_backup {
        let mut i = 1;
        loop {
            let bkp = format!("{}.~{}~", dest.display(), i);
            let bkp_path = PathBuf::from(bkp);
            if !bkp_path.exists() {
                fs::rename(dest, bkp_path)?;
                break;
            }
            i += 1;
        }
    }

    Ok(())
}

fn copy_parfile(src: &Path, dest: &Path, args: &Args, pb: &Arc<Option<ProgressBar>>, bytes_copied: &Arc<AtomicU64>) -> Result<()> {
    let mut src_file = fs::File::open(src)?;
    let mut dest_file = fs::OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(dest)?;

    let src_metadata = src_file.metadata()?;
    let total_len = src_metadata.len();

    // Reflink
    if args.reflink != "never" {
        #[cfg(target_os = "linux")]
        {
            const FICLONE: libc::c_ulong = 0x40049409;
            let ret = unsafe { libc::ioctl(dest_file.as_raw_fd(), FICLONE, src_file.as_raw_fd()) };
            if ret == 0 {
                bytes_copied.fetch_add(total_len, Ordering::SeqCst);
                if let Some(p) = pb.as_ref() {
                    p.set_position(bytes_copied.load(Ordering::SeqCst));
                }
                return Ok(());
            } else if args.reflink == "always" {
                return Err(anyhow!("Failed to reflink"));
            }
        }
    }

    // copy_file_range
    #[cfg(target_os = "linux")]
    {
        let mut offset = 0;
        while offset < total_len {
            let chunk_size = std::cmp::min(total_len - offset, 1024 * 1024 * 10) as usize;
            let ret = unsafe {
                libc::copy_file_range(src_file.as_raw_fd(), std::ptr::null_mut(), dest_file.as_raw_fd(), std::ptr::null_mut(), chunk_size, 0)
            };
            if ret < 0 { break; }
            if ret == 0 { break; }
            offset += ret as u64;
            bytes_copied.fetch_add(ret as u64, Ordering::SeqCst);
            if let Some(p) = pb.as_ref() {
                p.set_position(bytes_copied.load(Ordering::SeqCst));
            }
        }
        if offset == total_len {
            if args.fsync { dest_file.sync_all()?; }
            return Ok(());
        }
    }

    // Fallback
    src_file.seek(SeekFrom::Start(0))?;
    let mut buffer = vec![0u8; 1024 * 1024];
    loop {
        let n = src_file.read(&mut buffer)?;
        if n == 0 { break; }
        dest_file.write_all(&buffer[..n])?;
        bytes_copied.fetch_add(n as u64, Ordering::SeqCst);
        if let Some(p) = pb.as_ref() {
            p.set_position(bytes_copied.load(Ordering::SeqCst));
        }
    }

    if args.fsync { dest_file.sync_all()?; }
    Ok(())
}

fn copy_parblock(src: &Path, dest: &Path, args: &Args, pb: &Arc<Option<ProgressBar>>, bytes_copied: &Arc<AtomicU64>) -> Result<()> {
    let src_metadata = fs::metadata(src)?;
    let total_len = src_metadata.len();
    let block_size = parse_block_size(&args.block_size)?;

    let dest_file = fs::OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(dest)?;
    dest_file.set_len(total_len)?;

    let num_blocks = (total_len + block_size - 1) / block_size;

    (0..num_blocks).into_par_iter().for_each(|i| {
        let start = i * block_size;
        let len = std::cmp::min(block_size, total_len - start);

        let mut src_f = fs::File::open(src).unwrap();
        let mut dest_f = fs::OpenOptions::new().write(true).open(dest).unwrap();

        src_f.seek(SeekFrom::Start(start)).unwrap();
        dest_f.seek(SeekFrom::Start(start)).unwrap();

        #[cfg(target_os = "linux")]
        {
            let mut offset_in = start as i64;
            let mut offset_out = start as i64;
            let mut copied = 0;
            while copied < len {
                let ret = unsafe {
                    libc::copy_file_range(src_f.as_raw_fd(), &mut offset_in, dest_f.as_raw_fd(), &mut offset_out, (len - copied) as usize, 0)
                };
                if ret <= 0 { break; }
                copied += ret as u64;
                bytes_copied.fetch_add(ret as u64, Ordering::SeqCst);
                if let Some(p) = pb.as_ref() {
                    p.set_position(bytes_copied.load(Ordering::SeqCst));
                }
            }
            if copied == len { return; }
        }

        // Fallback
        let mut buffer = vec![0u8; 64 * 1024];
        let mut copied = 0;
        while copied < len {
            let to_read = std::cmp::min(buffer.len() as u64, len - copied) as usize;
            src_f.read_exact(&mut buffer[..to_read]).unwrap();
            dest_f.write_all(&buffer[..to_read]).unwrap();
            copied += to_read as u64;
            bytes_copied.fetch_add(to_read as u64, Ordering::SeqCst);
            if let Some(p) = pb.as_ref() {
                p.set_position(bytes_copied.load(Ordering::SeqCst));
            }
        }
    });

    if args.fsync {
        let dest_file = fs::File::open(dest)?;
        dest_file.sync_all()?;
    }

    Ok(())
}

#[cfg(unix)]
fn libc_mknod(path: &Path, mode: libc::mode_t, dev: libc::dev_t) -> Result<()> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;
    let c_path = CString::new(path.as_os_str().as_bytes())?;
    let ret = unsafe { libc::mknod(c_path.as_ptr(), mode, dev) };
    if ret < 0 {
        Err(anyhow::Error::from(io::Error::last_os_error()))
    } else {
        Ok(())
    }
}
