fn parse_block_size(s: &str) -> Result<u64> {
    let s = s.to_uppercase();
    let num_part: String = s.chars().take_while(|c| c.is_digit(10)).collect();
    let unit_part: String = s.chars().skip(num_part.len()).collect();
    let num: u64 = num_part.parse().context("Invalid number in block size")?;
    match unit_part.as_str() {
        "K" | "KB" => Ok(num * 1024),
        "M" | "MB" => Ok(num * 1024 * 1024),
        "G" | "GB" => Ok(num * 1024 * 1024 * 1024),
        "T" | "TB" => Ok(num * 1024 * 1024 * 1024 * 1024),
        "" | "B" => Ok(num),
        _ => Err(anyhow!("Invalid block size unit: {}", unit_part)),
    }
}

